#!/usr/bin/env python3
"""Final verification of all definition-of-done items."""
import json
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

def run_cmd(host, dtype, user, pwd, cmds):
    results = {}
    conn = ConnectHandler(host=host, device_type=dtype, username=user, password=pwd)
    for cmd in cmds:
        try:
            results[cmd] = conn.send_command(cmd, read_timeout=30)
        except Exception as e:
            results[cmd] = f"ERROR: {e}"
    conn.disconnect()
    return results

def main():
    print("=" * 60)
    print("1. ADJACENCIES AND SESSIONS")
    print("=" * 60)

    # HQ-Edge BGP + OSPF
    r = run_cmd("192.168.122.11", "vyos", "vyos", "test", [
        "show ip bgp summary",
        "show ip ospf neighbor",
        "show ip bgp",
        "show ip route",
        "show ip bgp neighbors 203.0.113.1 advertised-routes",
        "show ip bgp neighbors 203.0.113.5 advertised-routes",
    ])
    print("\n--- HQ-Edge BGP summary ---")
    print(r["show ip bgp summary"])
    print("\n--- HQ-Edge OSPF neighbors ---")
    print(r["show ip ospf neighbor"])
    print("\n--- HQ-Edge BGP table ---")
    print(r["show ip bgp"])
    print("\n--- HQ-Edge routes ---")
    print(r["show ip route"])
    print("\n--- HQ-Edge advertised to ISP-A ---")
    print(r["show ip bgp neighbors 203.0.113.1 advertised-routes"])
    print("\n--- HQ-Edge advertised to ISP-B ---")
    print(r["show ip bgp neighbors 203.0.113.5 advertised-routes"])

    # Hub-A
    r = run_cmd("192.168.122.12", "vyos", "vyos", "test", [
        "show ip ospf neighbor",
        "show ip route",
    ])
    print("\n--- Hub-A OSPF neighbors ---")
    print(r["show ip ospf neighbor"])
    print("\n--- Hub-A routes ---")
    print(r["show ip route"])

    # Hub-B
    r = run_cmd("192.168.122.13", "vyos", "vyos", "test", [
        "show ip ospf neighbor",
        "show ip route",
    ])
    print("\n--- Hub-B OSPF neighbors ---")
    print(r["show ip ospf neighbor"])
    print("\n--- Hub-B routes ---")
    print(r["show ip route"])

    # Branches
    for name, ip in [("Branch-1", "192.168.122.21"), ("Branch-2", "192.168.122.22"),
                      ("Branch-3", "192.168.122.23"), ("Branch-4", "192.168.122.24")]:
        r = run_cmd(ip, "mikrotik_routeros", "admin", "test", [
            "/routing ospf neighbor print detail",
            "/ip route print detail",
        ])
        print(f"\n--- {name} OSPF neighbors ---")
        print(r["/routing ospf neighbor print detail"])
        print(f"\n--- {name} routes ---")
        print(r["/ip route print detail"])

    print("\n" + "=" * 60)
    print("3. HOST REACHABILITY")
    print("=" * 60)

    non_guest = {
        "B1-PC1": ("192.168.122.31", "10.1.1.10"),
        "B1-PC2": ("192.168.122.32", "10.1.1.11"),
        "B2-PC1": ("192.168.122.33", "10.1.2.10"),
        "B2-PC2": ("192.168.122.34", "10.1.2.11"),
        "B3-PC1": ("192.168.122.35", "10.1.3.10"),
        "B3-PC2": ("192.168.122.36", "10.1.3.11"),
        "B4-PC1": ("192.168.122.37", "10.2.1.10"),
        "B4-PC2": ("192.168.122.38", "10.2.1.11"),
    }
    guest = {
        "B4-PC3": ("192.168.122.39", "10.2.2.10"),
        "B4-PC4": ("192.168.122.40", "10.2.2.11"),
    }
    all_hosts = {**non_guest, **guest}

    def ping_from(src_name, src_mgmt, dst_ip, count=2):
        try:
            conn = ConnectHandler(host=src_mgmt, device_type="linux", username="root", password="alpine")
            out = conn.send_command(f"ping -c {count} -W 3 {dst_ip}", read_timeout=15)
            conn.disconnect()
            return "0% packet loss" in out or "0.0% packet loss" in out
        except Exception as e:
            return False

    # Non-guest to non-guest
    print("\n--- Non-guest to non-guest pings ---")
    ng_names = list(non_guest.keys())
    results_ng = {}
    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = {}
        for src in ng_names:
            for dst in ng_names:
                if src == dst:
                    continue
                key = (src, dst)
                futures[pool.submit(ping_from, src, non_guest[src][0], non_guest[dst][1])] = key
        for f in as_completed(futures):
            key = futures[f]
            results_ng[key] = f.result()

    ng_pass = sum(1 for v in results_ng.values() if v)
    ng_fail = sum(1 for v in results_ng.values() if not v)
    print(f"  Pass: {ng_pass}, Fail: {ng_fail}")
