            results_gng[futures[f]] = f.result()

    gng_blocked = sum(1 for v in results_gng.values() if not v)
    gng_leaked = sum(1 for v in results_gng.values() if v)
    print(f"  Blocked (correct): {gng_blocked}/32, Leaked (wrong): {gng_leaked}")
    for k, v in sorted(results_gng.items()):
        if v:
            print(f"  LEAK: {k[0]} -> {k[1]}")

    # Internet pings
    print("\n--- Internet pings (20 pairs: 10 hosts x 2 targets) ---")
    results_inet = {}
    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = {}
        for name, (mgmt, lab) in all_hosts.items():
            for target in ["8.8.8.8", "1.1.1.1"]:
                key = (name, target)
                futures[pool.submit(ping_from, mgmt, target)] = key
        for f in as_completed(futures):
            results_inet[futures[f]] = f.result()

    inet_pass = sum(1 for v in results_inet.values() if v)
    inet_fail = sum(1 for v in results_inet.values() if not v)
    print(f"  Pass: {inet_pass}/20, Fail: {inet_fail}")
    for k, v in sorted(results_inet.items()):
        if not v:
            print(f"  FAIL: {k[0]} -> {k[1]}")

    print("\n" + "=" * 60)
    print("SUMMARY")
    print("=" * 60)
    all_pass = (ng_pass == 56 and gg_pass == 2 and gng_blocked == 32 and
                gng_leaked == 0 and inet_pass == 20 and inet_fail == 0)
    print(f"All checks passed: {all_pass}")

if __name__ == "__main__":
    main()
